/**
 * End-to-end measurement of the guest -> account activation funnel.
 *
 * Every other activation test mocks either the database or the service. This
 * one does neither: it POSTs real batches through the real `/api/analytics/app`
 * ingest route into a real Postgres, then reads them back through the real
 * `getActivationFunnel` aggregation. That is the only way to prove the two
 * halves actually agree — that what the sanitiser stores is what the SQL can
 * find, and that the reported rates match the traffic that produced them.
 *
 * Skips when DATABASE_URL is unset, matching analyticsAppTelemetryIngest.test.js.
 * To run it:
 *   docker run -d --name kubus-funnel-pg -e POSTGRES_PASSWORD=funnel \
 *     -e POSTGRES_USER=artkubus -e POSTGRES_DB=artkubus -p 55432:5432 \
 *     postgis/postgis:16-3.4
 *   psql -f src/db/schema_complete.sql && node src/db/migrate.js
 *   DATABASE_URL=postgresql://artkubus:funnel@127.0.0.1:55432/artkubus \
 *     npx jest __tests__/activationFunnelEndToEnd.test.js --runInBand
 */
process.env.NODE_ENV = process.env.NODE_ENV || 'development'
process.env.ANALYTICS_RATE_LIMIT_WINDOW_MS = '60000'
process.env.ANALYTICS_RATE_LIMIT_MAX = '100000'
process.env.ANALYTICS_APP_ALLOWED_PROPERTIES = 'app.kubus.site'
process.env.ANALYTICS_MAX_EVENTS = '200'

jest.mock('../src/middleware/requireWritableNode', () => ({
  requireWritableNode: () => (_req, _res, next) => next(),
}))

jest.mock('../src/services/cacheService', () => ({
  // The funnel caches for 60s; a measurement run needs to see each write.
  wrap: async (_key, fn) => fn(),
}))

const express = require('express')
const request = require('supertest')
const { randomUUID } = require('crypto')

const analyticsRouter = require('../src/routes/analytics')
const adminAnalyticsService = require('../src/services/adminAnalyticsService')
const { query, closePool } = require('../src/db')

const hasDb = () => Boolean((process.env.DATABASE_URL || '').trim())
const describeDb = hasDb() ? describe : describe.skip

const PROPERTY = 'app.kubus.site'
const CAMPAIGN_A = 'e2e_summer_art'
const CAMPAIGN_B = 'e2e_winter_art'

function makeApp() {
  const app = express()
  app.use(express.json({ limit: '256kb' }))
  app.use('/api/analytics', analyticsRouter)
  // eslint-disable-next-line no-unused-vars
  app.use((err, _req, res, _next) =>
    res.status(err.statusCode || 500).json({ success: false, error: err.message }),
  )
  return app
}

const baseMetadata = (overrides = {}) => ({
  property: PROPERTY,
  screen_name: 'MapScreen',
  screen_route: '/map',
  flow_stage: 'main',
  app_version: '0.7.2',
  build_number: 202608020,
  platform: 'web',
  env: 'prod',
  locale: 'en',
  ...overrides,
})

/**
 * One visitor's journey. `stages` are emitted in order, each a minute apart so
 * the median-duration percentiles have something real to measure.
 */
function journey({ sessionId, actorUserId, campaign, stages, startMinute = 0 }) {
  const base = Date.parse('2026-08-01T10:00:00.000Z')
  return stages.map((stage, index) => ({
    event_id: randomUUID(),
    event_time: new Date(base + (startMinute + index) * 60_000).toISOString(),
    event_type: stage,
    session_id: sessionId,
    actor_user_id:
      actorUserId && ['account_session_created', 'pending_action_restored', 'pending_action_completed'].includes(stage)
        ? actorUserId
        : null,
    metadata: baseMetadata({
      utm_source: 'meta',
      utm_medium: 'paid_social',
      utm_campaign: campaign,
      utm_content: 'creative_a',
      entry_intent: 'discover',
      guest: true,
      ...(stage === 'protected_action_clicked' || stage === 'pending_action_completed'
        ? { action_type: 'save', target_type: 'artwork', source_screen: 'map_marker' }
        : {}),
      ...(stage === 'account_session_created' ? { auth_method: 'google', is_new_account: true } : {}),
    }),
  }))
}

const FULL_FUNNEL = [
  'guest_app_loaded',
  'map_opened',
  'artwork_viewed',
  'protected_action_clicked',
  'auth_gate_viewed',
  'registration_submitted',
  'account_session_created',
  'pending_action_restored',
  'pending_action_completed',
]

describeDb('activation funnel, end to end against a real database', () => {
  const app = makeApp()
  const sessionIds = []

  const post = (events) =>
    request(app)
      .post('/api/analytics/app')
      .set('User-Agent', 'Mozilla/5.0')
      .send({ property: PROPERTY, events })

  beforeAll(async () => {
    // A cohort shaped like real ad traffic: most bounce early, a few activate.
    const batches = []

    // 12 sessions that load the app and the map, then leave. The "before"
    // population — the state the funnel work exists to change.
    for (let i = 0; i < 12; i++) {
      const sessionId = randomUUID()
      sessionIds.push(sessionId)
      batches.push(journey({
        sessionId,
        campaign: CAMPAIGN_A,
        stages: ['guest_app_loaded', 'map_opened'],
      }))
    }

    // 6 browse content but never attempt a protected action.
    for (let i = 0; i < 6; i++) {
      const sessionId = randomUUID()
      sessionIds.push(sessionId)
      batches.push(journey({
        sessionId,
        campaign: CAMPAIGN_A,
        stages: ['guest_app_loaded', 'map_opened', 'artwork_viewed'],
      }))
    }

    // 4 attempt Save and see the gate, but do not register.
    for (let i = 0; i < 4; i++) {
      const sessionId = randomUUID()
      sessionIds.push(sessionId)
      batches.push(journey({
        sessionId,
        campaign: CAMPAIGN_A,
        stages: ['guest_app_loaded', 'map_opened', 'artwork_viewed', 'protected_action_clicked', 'auth_gate_viewed'],
      }))
    }

    // 1 starts registration and stops there (the email verification wall).
    {
      const sessionId = randomUUID()
      sessionIds.push(sessionId)
      batches.push(journey({
        sessionId,
        campaign: CAMPAIGN_A,
        stages: [...FULL_FUNNEL.slice(0, 6)],
      }))
    }

    // 3 complete the whole funnel, including the original Save.
    for (let i = 0; i < 3; i++) {
      const sessionId = randomUUID()
      sessionIds.push(sessionId)
      batches.push(journey({
        sessionId,
        actorUserId: randomUUID(),
        campaign: CAMPAIGN_A,
        stages: FULL_FUNNEL,
      }))
    }

    // A second campaign, so the breakdown has something to separate.
    for (let i = 0; i < 5; i++) {
      const sessionId = randomUUID()
      sessionIds.push(sessionId)
      batches.push(journey({
        sessionId,
        campaign: CAMPAIGN_B,
        stages: ['guest_app_loaded', 'map_opened'],
      }))
    }
    {
      const sessionId = randomUUID()
      sessionIds.push(sessionId)
      batches.push(journey({
        sessionId,
        actorUserId: randomUUID(),
        campaign: CAMPAIGN_B,
        stages: FULL_FUNNEL,
      }))
    }

    for (const events of batches) {
      const res = await post(events)
      if (res.status !== 204) {
        throw new Error(`ingest failed: ${res.status} ${JSON.stringify(res.body)}`)
      }
    }
  }, 120_000)

  afterAll(async () => {
    try {
      if (sessionIds.length) {
        await query('DELETE FROM public.analytics_events WHERE session_id = ANY($1::text[])', [sessionIds])
      }
    } finally {
      try {
        await closePool()
      } catch {
        /* ignore */
      }
    }
  }, 60_000)

  const range = {
    property: PROPERTY,
    from: '2026-08-01T00:00:00.000Z',
    to: '2026-08-02T00:00:00.000Z',
  }

  test('ingested events are stored with campaign attribution on the columns', async () => {
    const res = await query(
      `SELECT utm_source, utm_medium, utm_campaign, utm_content, metadata->>'locale' AS locale
         FROM public.analytics_events
        WHERE session_id = ANY($1::text[]) AND event_type = 'account_session_created'
        LIMIT 1`,
      [sessionIds],
    )

    expect(res.rows).toHaveLength(1)
    // The bug this whole change exists to fix: these used to be dropped.
    expect(res.rows[0].utm_source).toBe('meta')
    expect(res.rows[0].utm_medium).toBe('paid_social')
    expect(res.rows[0].utm_campaign).toBe(CAMPAIGN_A)
    expect(res.rows[0].utm_content).toBe('creative_a')
    expect(res.rows[0].locale).toBe('en')
  })

  test('the funnel reports the cohort that was actually ingested', async () => {
    const data = await adminAnalyticsService.getActivationFunnel(range)
    const byStage = Object.fromEntries(data.stages.map((s) => [s.stage, s]))

    // 12 + 6 + 4 + 1 + 3 on campaign A, plus 5 + 1 on campaign B = 32 sessions.
    expect(byStage.guest_app_loaded.sessions).toBe(32)
    expect(byStage.map_opened.sessions).toBe(32)
    // 6 + 4 + 1 + 3 + 1 viewed content.
    expect(byStage.artwork_viewed.sessions).toBe(15)
    // 4 + 1 + 3 + 1 attempted a protected action.
    expect(byStage.protected_action_clicked.sessions).toBe(9)
    expect(byStage.auth_gate_viewed.sessions).toBe(9)
    // 1 + 3 + 1 started registration.
    expect(byStage.registration_submitted.sessions).toBe(5)
    // 3 + 1 reached a usable session.
    expect(byStage.account_session_created.sessions).toBe(4)
    expect(byStage.pending_action_completed.sessions).toBe(4)
  })

  test('conversion, abandonment and unique users are computed from real rows', async () => {
    const data = await adminAnalyticsService.getActivationFunnel(range)
    const byStage = Object.fromEntries(data.stages.map((s) => [s.stage, s]))

    // 15 of 32 sessions that opened the map viewed content.
    expect(byStage.artwork_viewed.conversionFromPrevious).toBeCloseTo(15 / 32, 4)
    expect(byStage.artwork_viewed.abandonedFromPrevious).toBe(17)
    // 9 of 15 attempted a protected action.
    expect(byStage.protected_action_clicked.conversionFromPrevious).toBeCloseTo(9 / 15, 4)
    // 4 of 5 who started registration got a session.
    expect(byStage.account_session_created.conversionFromPrevious).toBeCloseTo(4 / 5, 4)

    // actor_user_id is only attached from account_session_created onward.
    expect(byStage.account_session_created.uniqueUsers).toBe(4)
    expect(byStage.guest_app_loaded.uniqueUsers).toBe(0)

    expect(data.totals.entrySessions).toBe(32)
    expect(data.totals.activatedSessions).toBe(4)
    expect(data.totals.activationRate).toBeCloseTo(4 / 32, 4)
    expect(data.totals.completionRate).toBeCloseTo(1, 4)
  })

  test('median durations are measured, not defaulted', async () => {
    const data = await adminAnalyticsService.getActivationFunnel(range)

    // Each journey advances one minute per stage: map_opened -> artwork_viewed
    // -> protected_action_clicked is two steps.
    expect(data.medianDurationsSeconds.mapToProtectedAction).toBe(120)
    // protected_action_clicked -> auth_gate_viewed -> registration_submitted
    // -> account_session_created is three steps.
    expect(data.medianDurationsSeconds.protectedActionToSession).toBe(180)
    // account_session_created -> pending_action_restored -> completed.
    expect(data.medianDurationsSeconds.sessionToActionCompleted).toBe(120)
  })

  test('campaign breakdown separates the two campaigns correctly', async () => {
    const data = await adminAnalyticsService.getActivationFunnel({
      ...range,
      breakdown: 'campaign',
    })

    const rows = Object.fromEntries(data.breakdownRows.map((r) => [r.dimension, r]))

    expect(rows[CAMPAIGN_A].mapSessions).toBe(26)
    expect(rows[CAMPAIGN_A].activatedSessions).toBe(3)
    expect(rows[CAMPAIGN_A].activationRate).toBeCloseTo(3 / 26, 4)

    expect(rows[CAMPAIGN_B].mapSessions).toBe(6)
    expect(rows[CAMPAIGN_B].activatedSessions).toBe(1)
    expect(rows[CAMPAIGN_B].activationRate).toBeCloseTo(1 / 6, 4)

    // Campaign B converts better despite far less traffic — exactly the
    // comparison the breakdown exists to make possible.
    expect(rows[CAMPAIGN_B].activationRate).toBeGreaterThan(rows[CAMPAIGN_A].activationRate)
  })

  test('a locale breakdown works off metadata rather than a column', async () => {
    const data = await adminAnalyticsService.getActivationFunnel({
      ...range,
      breakdown: 'locale',
    })

    const rows = Object.fromEntries(data.breakdownRows.map((r) => [r.dimension, r]))
    expect(rows.en.mapSessions).toBe(32)
    expect(rows.en.activatedSessions).toBe(4)
  })
})
